input.command:
cd /tmp/sdspec && awk '/^### /{lbl=$0; getline; getline exitl; sub(/^EXIT: /,"",exitl); firstout=""; nout=0; err=""} 
/^ o\|/{nout++; if(nout==1) firstout=$0}
/^ e\|/{err=err "\n    " $0}
/^$/{ if(lbl!=""){printf "%s | EXIT=%s | outlines=%d | first_out=%s%s\n", lbl, exitl, nout, firstout, err; lbl=""} }
END{}' /tmp/sdspec/log_hv.txt
